async function main() {
  const url = new URL("https://api.aimlapi.com/v1/models/deprecations");
  url.searchParams.set("status", "withdrawn");
  url.searchParams.set("since", "2026-08-01");

  const response = await fetch(url);
  const data = await response.json();
  console.log(JSON.stringify(data, null, 2));
}

main();
